#!/usr/bin/env python3
"""Генерує пакети марок (packs/*.json) і каталог packs/index.json.

Програма завантажує каталог з GitHub:
  https://raw.githubusercontent.com/romanslbdn-sudo/AutoScan/main/packs/index.json
Щоб додати нову марку — допишіть її сюди, запустіть скрипт і викладіть зміни в репозиторій.
Пакет з'явиться в програмі автоматично (розділ «Бази авто» → «Пакети в інтернеті»).

У пакети додаються лише коди, значення яких добре відоме. Заводські коди можуть
трохи відрізнятися між моделями й роками — це вказано в примітках.
"""
import json, os

PACKS = []

def pack(id, brand, title, matches, notes, codes, version="1.0"):
    PACKS.append({"id": id, "brand": brand, "title": title, "version": version,
                  "matches": matches, "notes": notes,
                  "codes": [{"c": c, "t": t, "d": d, "r": r, "s": s} for c, t, d, r, s in codes]})

pack("ford", "Ford", "Ford: заводські коди", ["Ford"],
     "Коди Ford для двигунів з OBD2. Значення можуть відрізнятися для окремих моделей — у разі сумніву перевірте за документацією Ford.",
     [
         ("P1000", "Самодіагностика ще не завершена", "Це не несправність: блок ще не завершив усі самоперевірки після стирання помилок або відключення акумулятора. Зникне після кількох поїздок.", ["Нещодавно стирали помилки або відключали акумулятор"], 1),
         ("P1131", "Лямбда-зонд 1 (ряд 1) не перемикається — показує бідну суміш", "Перший лямбда-зонд постійно показує бідну суміш і не перемикається.", ["Підсмоктування повітря", "Низький тиск палива", "Зношений лямбда-зонд", "Забруднений ДМРВ"], 2),
         ("P1151", "Лямбда-зонд 1 (ряд 2) не перемикається — показує бідну суміш", "Перший лямбда-зонд другого ряду постійно показує бідну суміш.", ["Підсмоктування повітря", "Низький тиск палива", "Зношений лямбда-зонд"], 2),
         ("P1260", "Виявлено спробу угону — двигун заблоковано", "Іммобілайзер не впізнав ключ і заблокував запуск двигуна.", ["Ключ без запрограмованого чипа", "Розряджений або пошкоджений чип ключа", "Несправна антена іммобілайзера біля замка запалювання"], 2),
         ("P1285", "Перегрів головки блока циліндрів", "Датчик температури головки блока показав перегрів. Негайно зупиніться!", ["Низький рівень охолоджувальної рідини", "Несправний вентилятор або термостат", "Несправний датчик температури головки"], 3),
         ("P1299", "Увімкнено захист від перегріву головки блока", "Блок перейшов у захисний режим через перегрів: частина циліндрів може вимикатися.", ["Перегрів двигуна", "Витік охолоджувальної рідини", "Несправний вентилятор"], 3),
         ("P1401", "Високий сигнал датчика перепаду тиску EGR (DPFE)", "Датчик перепаду тиску системи EGR показує зависоке значення.", ["Тріснуті або від'єднані шланги датчика DPFE", "Несправний датчик DPFE", "Забитий канал EGR"], 2),
         ("P1450", "Не вдається створити розрідження в паливному баку (EVAP)", "Система EVAP не може створити розрідження під час самоперевірки.", ["Забитий фільтр або клапан вентиляції адсорбера", "Перегнутий шланг EVAP", "Несправний клапан продувки"], 1),
     ])

